INSERT INTO skills (code, subject_code, name) VALUES
    ('MORE_FEWER_PK', 'MATH', 'More and Fewer'),
    ('OPPOSITES_PK', 'ENGLISH', 'Opposites');
INSERT INTO lessons (id, code, subject_code, grade_level, display_order, title, description) VALUES
    ('12000000-0000-0000-0000-000000000018', 'PK-MORE-01', 'MATH', 'PRE_K', 10, 'More and Fewer', 'Look at two groups and tell which has more.'),
    ('12000000-0000-0000-0000-000000000019', 'PK-ENG-OPPOSITE-01', 'ENGLISH', 'PRE_K', 9, 'Opposites', 'Learn pairs of words that mean the opposite.');
INSERT INTO exercises (id, lesson_code, skill_code, display_order, prompt, answer_index, explanation, hint) VALUES
    ('32000000-0000-0000-0000-000000000001', 'PK-COUNT1-01', 'COUNT_1_5', 4, 'Count the ducks: duck. How many ducks?', 0, 'There is just 1 duck.', 'Point to the duck and say one.'),
    ('32000000-0000-0000-0000-000000000002', 'PK-COUNT1-01', 'COUNT_1_5', 5, 'Count the cars: car car car car. How many cars?', 2, 'There are 4 cars: 1, 2, 3, 4.', 'Touch each car as you count.'),
    ('32000000-0000-0000-0000-000000000003', 'PK-COUNT1-01', 'COUNT_1_5', 6, 'What number comes after 2?', 2, 'We count 1, 2, 3. After 2 comes 3.', 'Count from 1 and stop after 2.'),
    ('32000000-0000-0000-0000-000000000004', 'PK-COUNT2-01', 'COUNT_6_10', 4, 'Count the flowers: flower flower flower flower flower flower. How many flowers?', 2, 'There are 6 flowers.', 'Count slowly and touch each one.'),
    ('32000000-0000-0000-0000-000000000005', 'PK-COUNT2-01', 'COUNT_6_10', 5, 'Count the bees: bee bee bee bee bee bee bee bee bee. How many bees?', 0, 'There are 9 bees.', 'Count very carefully. Go slow!'),
    ('32000000-0000-0000-0000-000000000006', 'PK-COUNT2-01', 'COUNT_6_10', 6, 'What number comes after 9?', 2, 'We count 8, 9, 10. After 9 comes 10.', 'Count to 10 on your fingers.'),
    ('32000000-0000-0000-0000-000000000007', 'PK-SHAPE-01', 'SHAPES_PK', 4, 'Which shape looks like a slice of pizza?', 0, 'A pizza slice has 3 sides, like a triangle.', 'It is pointy at one end.'),
    ('32000000-0000-0000-0000-000000000008', 'PK-SHAPE-01', 'SHAPES_PK', 5, 'Which shape looks like a window with 4 equal sides?', 1, 'A square has 4 sides that are all the same.', 'All four sides match.'),
    ('32000000-0000-0000-0000-000000000009', 'PK-SHAPE-01', 'SHAPES_PK', 6, 'Which shape looks like a cookie?', 0, 'Most cookies are round like a circle.', 'It is round.'),
    ('32000000-0000-0000-0000-000000000010', 'PK-SIZE-01', 'SIZE_COMPARE', 4, 'A tree and a leaf. Which one is bigger?', 1, 'A tree is much bigger than one leaf.', 'Leaves grow on it.'),
    ('32000000-0000-0000-0000-000000000011', 'PK-SIZE-01', 'SIZE_COMPARE', 5, 'An ant and a dog. Which one is smaller?', 1, 'An ant is tiny, much smaller than a dog.', 'Which one could fit on your finger?'),
    ('32000000-0000-0000-0000-000000000012', 'PK-SIZE-01', 'SIZE_COMPARE', 6, 'A house and a shoe. Which one is bigger?', 0, 'A house is much bigger than a shoe.', 'Which one can you live in?'),
    ('32000000-0000-0000-0000-000000000013', 'PK-SAME-01', 'SAME_DIFF', 4, 'A big ball and a small ball. Are they the same size?', 1, 'One is big and one is small, so they are different sizes.', 'Big and small are different.'),
    ('32000000-0000-0000-0000-000000000014', 'PK-SAME-01', 'SAME_DIFF', 5, 'Two yellow ducks that look just alike. Are they the same?', 0, 'They look just alike, so they are the same.', 'Look for any difference.'),
    ('32000000-0000-0000-0000-000000000015', 'PK-SAME-01', 'SAME_DIFF', 6, 'A circle and a square. Are they the same shape?', 1, 'A circle is round and a square has corners, so they are different.', 'Does one have corners?'),
    ('32000000-0000-0000-0000-000000000016', 'PK-PATTERN-01', 'PATTERNS_PK', 4, 'What comes next: cat, dog, cat, dog, __?', 2, 'The pattern is cat, dog, cat, dog, so next is cat.', 'Say the pattern out loud.'),
    ('32000000-0000-0000-0000-000000000017', 'PK-PATTERN-01', 'PATTERNS_PK', 5, 'What comes next: big, small, big, small, __?', 0, 'The pattern is big, small, so after small comes big.', 'What comes after small each time?'),
    ('32000000-0000-0000-0000-000000000018', 'PK-PATTERN-01', 'PATTERNS_PK', 6, 'What comes next: clap, stomp, clap, stomp, __?', 0, 'The pattern is clap, stomp, so next is clap.', 'Try doing the pattern with your body!'),
    ('32000000-0000-0000-0000-000000000019', 'PK-POSITION-01', 'POSITION_WORDS', 4, 'A cat is sleeping behind the sofa. Where is the cat?', 0, 'The cat is behind the sofa, at its back.', 'Listen to the word before "the sofa".'),
    ('32000000-0000-0000-0000-000000000020', 'PK-POSITION-01', 'POSITION_WORDS', 5, 'A plane is flying above the clouds. Where is the plane?', 2, 'The plane is above, which means higher than the clouds.', 'Above means up higher.'),
    ('32000000-0000-0000-0000-000000000021', 'PK-POSITION-01', 'POSITION_WORDS', 6, 'Mia stands next to her friend. Where is Mia?', 2, 'Next to means beside.', 'Next to means right at the side.'),
    ('32000000-0000-0000-0000-000000000022', 'PK-COLOR-01', 'COLORS_PK', 4, 'What color is grass?', 1, 'Grass is green.', 'Look outside at a lawn.'),
    ('32000000-0000-0000-0000-000000000023', 'PK-COLOR-01', 'COLORS_PK', 5, 'What color is the sky on a sunny day?', 1, 'On a sunny day the sky is blue.', 'Look up on a nice day!'),
    ('32000000-0000-0000-0000-000000000024', 'PK-COLOR-01', 'COLORS_PK', 6, 'What color is chocolate?', 1, 'Chocolate is brown.', 'Think of a chocolate bar.'),
    ('32000000-0000-0000-0000-000000000025', 'PK-SORT-01', 'SORTING_PK', 4, 'Which one does not belong: shoe, sock, boot, banana?', 0, 'Shoe, sock, and boot go on your feet. A banana is a food.', 'Which one do you eat?'),
    ('32000000-0000-0000-0000-000000000026', 'PK-SORT-01', 'SORTING_PK', 5, 'Which one is an animal: lion, spoon, or ball?', 0, 'A lion is an animal.', 'Which one is alive and can roar?'),
    ('32000000-0000-0000-0000-000000000027', 'PK-SORT-01', 'SORTING_PK', 6, 'Which one can fly: bird, fish, or cow?', 0, 'Birds have wings and can fly.', 'Which one has wings?'),
    ('32000000-0000-0000-0000-000000000028', 'PK-ENG-LETTERS1-01', 'LETTERS_A_M', 4, 'What letter does "Cat" start with?', 1, 'Cat starts with the letter C.', 'C-a-t.'),
    ('32000000-0000-0000-0000-000000000029', 'PK-ENG-LETTERS1-01', 'LETTERS_A_M', 5, 'Which letter comes right after D?', 1, 'A, B, C, D, E. After D comes E.', 'Sing the alphabet song.'),
    ('32000000-0000-0000-0000-000000000030', 'PK-ENG-LETTERS1-01', 'LETTERS_A_M', 6, 'What letter does "Moon" start with?', 0, 'Moon starts with M.', 'Mmm-oon.'),
    ('32000000-0000-0000-0000-000000000031', 'PK-ENG-LETTERS2-01', 'LETTERS_N_Z', 4, 'What letter does "Sun" start with?', 0, 'Sun starts with S.', 'Sss-un.'),
    ('32000000-0000-0000-0000-000000000032', 'PK-ENG-LETTERS2-01', 'LETTERS_N_Z', 5, 'What letter does "Rabbit" start with?', 2, 'Rabbit starts with R.', 'Rrr-abbit.'),
    ('32000000-0000-0000-0000-000000000033', 'PK-ENG-LETTERS2-01', 'LETTERS_N_Z', 6, 'Which letter comes right after T?', 1, 'R, S, T, U. After T comes U.', 'Sing the alphabet song from Q.'),
    ('32000000-0000-0000-0000-000000000034', 'PK-ENG-SOUNDS-01', 'LETTER_SOUNDS_PK', 4, 'What sound does "Fish" start with?', 1, 'Fish starts with the fff sound: F.', 'Fff-ish.'),
    ('32000000-0000-0000-0000-000000000035', 'PK-ENG-SOUNDS-01', 'LETTER_SOUNDS_PK', 5, 'What sound does "Milk" start with?', 0, 'Milk starts with the mmm sound: M.', 'Close your lips: mmm.'),
    ('32000000-0000-0000-0000-000000000036', 'PK-ENG-SOUNDS-01', 'LETTER_SOUNDS_PK', 6, 'What sound does "Pig" start with?', 0, 'Pig starts with the puh sound: P.', 'A little puff of air: puh.'),
    ('32000000-0000-0000-0000-000000000037', 'PK-ENG-RHYME-01', 'RHYMING_PK', 4, 'Which word rhymes with "bee"?', 1, 'Bee and tree both end in -ee.', 'Listen to the end: bee, tr-ee.'),
    ('32000000-0000-0000-0000-000000000038', 'PK-ENG-RHYME-01', 'RHYMING_PK', 5, 'Which word rhymes with "car"?', 0, 'Car and star both end in -ar.', 'Listen to the end sound.'),
    ('32000000-0000-0000-0000-000000000039', 'PK-ENG-RHYME-01', 'RHYMING_PK', 6, 'Which word rhymes with "frog"?', 0, 'Frog and log both end in -og.', 'Fr-og, l-og.'),
    ('32000000-0000-0000-0000-000000000040', 'PK-ENG-LISTEN-01', 'LISTENING_PK', 4, 'A puppy played in the mud and needed a bath. Why did the puppy need a bath?', 0, 'The puppy got muddy, so it needed a bath.', 'What made the puppy dirty?'),
    ('32000000-0000-0000-0000-000000000041', 'PK-ENG-LISTEN-01', 'LISTENING_PK', 5, 'A boy wore his raincoat because it was raining. What was the weather?', 1, 'He wore a raincoat because it was raining.', 'Why do we wear raincoats?'),
    ('32000000-0000-0000-0000-000000000042', 'PK-ENG-LISTEN-01', 'LISTENING_PK', 6, 'Grandma read a book to Lily at bedtime. Who read the book?', 2, 'Grandma read the book to Lily.', 'Who was reading?'),
    ('32000000-0000-0000-0000-000000000043', 'PK-ENG-VOCAB-01', 'VOCAB_PK', 4, 'What do you sleep in?', 2, 'We sleep in a bed.', 'Where do you go at night?'),
    ('32000000-0000-0000-0000-000000000044', 'PK-ENG-VOCAB-01', 'VOCAB_PK', 5, 'What do you use to eat soup?', 0, 'A spoon holds soup.', 'Soup is runny!'),
    ('32000000-0000-0000-0000-000000000045', 'PK-ENG-VOCAB-01', 'VOCAB_PK', 6, 'What do you wear when it is cold outside?', 1, 'A coat keeps you warm.', 'What keeps you warm?'),
    ('32000000-0000-0000-0000-000000000046', 'PK-ENG-SOUNDDISC-01', 'SOUND_DISCRIM', 4, 'Which word starts with the same sound as "ball"?', 2, 'Ball and bear both start with b.', 'Buh-ball, buh-...'),
    ('32000000-0000-0000-0000-000000000047', 'PK-ENG-SOUNDDISC-01', 'SOUND_DISCRIM', 5, 'Which word starts with the same sound as "sun"?', 2, 'Sun and sock both start with s.', 'Sss-un, sss-...'),
    ('32000000-0000-0000-0000-000000000048', 'PK-ENG-SOUNDDISC-01', 'SOUND_DISCRIM', 6, 'Which two words start with the same sound?', 2, 'Map and mop both start with mmm.', 'Say the first sound of each word.'),
    ('32000000-0000-0000-0000-000000000049', 'PK-ENG-DIRECTIONS-01', 'DIRECTIONS_PK', 4, 'If your teacher says "clap two times," how many times should you clap?', 0, 'Two times means clap, clap.', 'Listen for the number.'),
    ('32000000-0000-0000-0000-000000000050', 'PK-ENG-DIRECTIONS-01', 'DIRECTIONS_PK', 5, 'If your teacher says "put the block in the box," where does the block go?', 0, 'The block goes in the box.', 'Listen to where it should go.'),
    ('32000000-0000-0000-0000-000000000051', 'PK-ENG-DIRECTIONS-01', 'DIRECTIONS_PK', 6, 'If your teacher says "first wash your hands, then eat," what do you do first?', 0, '"First" tells you to wash your hands before you eat.', 'Listen for the word "first".'),
    ('32000000-0000-0000-0000-000000000052', 'PK-MORE-01', 'MORE_FEWER_PK', 1, 'Which group has more: 2 cats or 4 cats?', 1, '4 is more than 2.', 'Count each group.'),
    ('32000000-0000-0000-0000-000000000053', 'PK-MORE-01', 'MORE_FEWER_PK', 2, 'Which group has fewer: 5 balls or 1 ball?', 1, '1 is fewer than 5.', 'Fewer means less.'),
    ('32000000-0000-0000-0000-000000000054', 'PK-MORE-01', 'MORE_FEWER_PK', 3, 'Which group has more: apple apple apple, or apple?', 1, 'The first group has 3 apples and the second has 1, so the first has more.', 'Count the apples in each group.'),
    ('32000000-0000-0000-0000-000000000055', 'PK-MORE-01', 'MORE_FEWER_PK', 4, 'Do 3 cups and 3 plates have the same number?', 0, '3 and 3 are the same number.', 'Count both groups.'),
    ('32000000-0000-0000-0000-000000000056', 'PK-MORE-01', 'MORE_FEWER_PK', 5, 'You have 2 cookies. Your friend has 2 cookies. Who has more?', 2, '2 and 2 are the same, so nobody has more.', 'Are the numbers the same?'),
    ('32000000-0000-0000-0000-000000000057', 'PK-MORE-01', 'MORE_FEWER_PK', 6, 'Which group has fewer: 3 stars or 6 stars?', 2, '3 is fewer than 6.', 'Which number is smaller?'),
    ('32000000-0000-0000-0000-000000000058', 'PK-ENG-OPPOSITE-01', 'OPPOSITES_PK', 1, 'What is the opposite of "big"?', 0, 'Big and small are opposites.', 'Think of a tiny mouse.'),
    ('32000000-0000-0000-0000-000000000059', 'PK-ENG-OPPOSITE-01', 'OPPOSITES_PK', 2, 'What is the opposite of "wet"?', 1, 'Wet and dry are opposites.', 'What are you after a towel?'),
    ('32000000-0000-0000-0000-000000000060', 'PK-ENG-OPPOSITE-01', 'OPPOSITES_PK', 3, 'What is the opposite of "day"?', 1, 'Day and night are opposites.', 'When do you see the moon?'),
    ('32000000-0000-0000-0000-000000000061', 'PK-ENG-OPPOSITE-01', 'OPPOSITES_PK', 4, 'What is the opposite of "in"?', 0, 'In and out are opposites.', 'Go in the door, then go...'),
    ('32000000-0000-0000-0000-000000000062', 'PK-ENG-OPPOSITE-01', 'OPPOSITES_PK', 5, 'What is the opposite of "loud"?', 0, 'Loud and quiet are opposites.', 'Shh! Be...'),
    ('32000000-0000-0000-0000-000000000063', 'PK-ENG-OPPOSITE-01', 'OPPOSITES_PK', 6, 'What is the opposite of "full"?', 0, 'Full and empty are opposites.', 'A cup with nothing in it is...');
